//! Independent ordinary rune altar World actions; pinned Wiki recipe facts, no developer tests invoked.
use gielinor_world::{simulation::{World,PlayerData,ActorId,Action,WorldEvent},runecrafting::{Config,Recipe},locations::Location,loc_collision::{self,LocCollision},inventory::Item,stats::Stats,npc::RandomSource,CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("ordinary rune binding unexpectedly drew RNG")}}
const ROWS:[(u32,i32,u8,u16,u8);6]=[(34760,556,1,50,11),(34761,558,2,55,14),(34762,555,5,60,19),(34763,557,9,65,26),(34764,554,14,70,35),(34765,559,20,75,46)];
fn fixture(row:usize,member:bool,kind:usize,current:u8,count:usize,rate:i32)->(World,ActorId,Location,Vec<(usize,i32)>){let(id,output,level,xp,interval)=ROWS[row];let mut w=World::default();for x in [3216,3224]{for z in [3216,3224]{w.collision.allocate(x,z,0);}}let location=Location::new(CoordGrid::new(3221,3220,0).unwrap(),id,10,0).unwrap();let ty=LocCollision{width:3,length:3,block_walk:2,block_range:true,break_route_finding:false};w.location_types.insert(id,ty);w.locations.load(location);loc_collision::toggle(&mut w.collision,location.coords,location.shape,location.angle,ty,true).unwrap();w.runecrafting=Some(Config{altars:[(id,Recipe{output,level,xp_tenths:xp,interval,name:"independent rune"})].into(),blocked_held:[26879,28593,28595,28597,28599].into(),blocked_worn:[26850].into(),animation:791,spot:186});w.object_types.stackable.insert(output);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(20,99);stats.set_current(20,current as i8);stats.set_fine_xp(20,130344311).unwrap();let mut d=PlayerData::new(1,"Independent rune binder".into(),CoordGrid::new(3220,3220,0).unwrap(),stats);d.xp_rate_hundreds=rate;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}let mut parts=vec![];for k in 0..count{let slot=(k*9+7)%28;let id=match kind{0=>1436,1=>7936,_=>if k%2==0{1436}else{7936}};d.inventory.restore_slot(slot,Some(Item{id,count:1,vars:0})).unwrap();parts.push((slot,id));}d.equipment.restore_slot(0,Some(Item{id:1155,count:1,vars:7})).unwrap();d.equipment.restore_slot(4,Some(Item{id:1129,count:1,vars:9})).unwrap();w.queue_login(1,d).unwrap();w.tick_with_random(&mut NoDraw).unwrap();let actor=w.actors().next().unwrap();w.set_membership(actor,member).unwrap();w.drain_events();(w,actor,location,parts)}
fn request(w:&mut World,a:ActorId,location:Location){assert!(w.has_location_handler(location.id,1));assert!(!w.has_location_handler(location.id,2));w.submit(a,Action::OperateLocation{coords:location.coords,id:location.id,operation:1,control:false}).unwrap();w.tick_with_random(&mut NoDraw).unwrap();}

fn special(w:&mut World,a:ActorId,parts:&[(usize,i32)]){for(slot,_)in parts{w.data_mut(a).unwrap().inventory.restore_slot(*slot,Some(Item{id:24704,count:1,vars:0})).unwrap();}}

fn finish(w:&mut World,a:ActorId,l:Location,parts:&[(usize,i32)],row:usize,current:u8,rate:i32,levelup:bool){let before=w.data(a).unwrap().clone();let mut bag=before.inventory.clone();for(slot,_)in parts{bag.restore_slot(*slot,None).unwrap();}bag.restore_slot(parts.iter().map(|p|p.0).min().unwrap(),Some(Item{id:ROWS[row].1,count:parts.len()as i32*(i32::from(current/ROWS[row].4)+1),vars:0})).unwrap();let mut stats=before.stats.clone();stats.set_fine_xp(20,stats.fine_xp(20)+parts.len()as i32*i32::from(ROWS[row].3)*150*rate/10000).unwrap();if levelup{stats.set_base(20,current as i8+1);stats.set_current(20,current as i8+1);}request(w,a,l);assert_eq!(w.data(a).unwrap().inventory,before.inventory);w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().stats,stats);assert_eq!(w.data(a).unwrap().equipment,before.equipment);}
#[test]fn thirty_six_special_essence_yield_edges_and_twelve_actual_levelups(){let mut n=0;for row in 0..6{for rate in[125,500]{let interval=ROWS[row].4;for current in[interval-1,interval,interval+1]{let(mut w,a,l,p)=fixture(row,true,2,current,7,rate);special(&mut w,a,&p);finish(&mut w,a,l,&p,row,current,rate,false);n+=1;}let current=interval-1;let(mut w,a,l,p)=fixture(row,true,2,current,1,rate);special(&mut w,a,&p);w.data_mut(a).unwrap().stats.set_base(20,current as i8);w.data_mut(a).unwrap().stats.set_fine_xp(20,gielinor_world::skills::xp_from_level(interval).unwrap()*10-1).unwrap();finish(&mut w,a,l,&p,row,current,rate,true);n+=1;}}assert_eq!(n,48);println!("PG_DAEYALT_BOUNDARY48 all6 yieldintervalminus/equal/plus1 rates125500 and12actualXPthresholdcrossings no retroactiveyield PASS");}
#[test]fn twelve_exact_max_credit_and_overflow_cases_and_six_zero_restore_boundaries(){for row in 0..6{for fits in[false,true]{let(mut w,a,l,p)=fixture(row,true,2,99,7,125);special(&mut w,a,&p);let output=ROWS[row].1;let produced=7*(i32::from(99/ROWS[row].4)+1);let stock=i32::MAX-produced+if fits{0}else{1};w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:output,count:stock,vars:0})).unwrap();let before=w.data(a).unwrap().clone();request(&mut w,a,l);w.tick_with_random(&mut NoDraw).unwrap();let mut bag=before.inventory.clone();let mut stats=before.stats.clone();if fits{for(slot,_)in &p{bag.restore_slot(*slot,None).unwrap();}bag.restore_slot(0,Some(Item{id:output,count:i32::MAX,vars:0})).unwrap();stats.set_fine_xp(20,130344311+7*i32::from(ROWS[row].3)*150*125/10000).unwrap();}assert_eq!(w.data(a).unwrap().inventory,bag);assert_eq!(w.data(a).unwrap().stats,stats);assert_eq!(w.data(a).unwrap().equipment,before.equipment);}let(w,a,_,_)=fixture(row,true,2,99,7,125);let mut bag=w.data(a).unwrap().inventory.clone();let before=bag.clone();assert!(bag.restore_slot(0,Some(Item{id:ROWS[row].1,count:0,vars:0})).is_err());assert_eq!(bag,before);}println!("PG_DAEYALT_BOUNDARY12 exacti32MAX fullcredit/oneextra refusal +6zeroStock rejected by publicrestore beforekernel;no privatezero-slot injection claim PASS");}
